#!/usr/bin/env python3
"""Write the generated files of arith/<function>/harness/ for the phase 1 functions of the frequency-domain suite (arith brief 161, owner decision 24): the packaged verification harness a user
reruns against their own instance. Handwritten and committed in each harness folder: chk_top.sv and coverage.yaml. Generated here from the repository's own files, so the harness cannot drift from
the bench the repository tests: model.py (and the models it needs), bench.py, frames.py, fcover.py, <function>_cocotb.py, assertions.sv (the checker modules the function uses), run_harness.py and README.md.

    python3 -m arith.tools.gen_harness_fft [fft_bfp ...] [--check]"""
from __future__ import annotations

import argparse
import re
import sys
from pathlib import Path

from arith.tools import arith_common as ac

FUNCTIONS = ("fft_bfp", "fft_mdc2", "fft_real_axis", "fft_fastconv")
MODES = {"fft_bfp": ["directed", "levels", "randomised", "stalled", "stalled_hard"], "fft_mdc2": ["directed", "randomised", "gaps"], "fft_real_axis": ["directed", "randomised", "checker"],
         "fft_fastconv": ["directed", "randomised", "axil", "saturate"]}
CHECKERS = {"fft_bfp": ["frame_checker.sv"], "fft_mdc2": ["frame_checker.sv"], "fft_real_axis": ["axis_checker.sv"], "fft_fastconv": ["axis_checker.sv", "axil_checker.sv"]}
SUPPORT = {"fft_bfp": ["fft_ref.py"], "fft_mdc2": ["fft_ref.py"], "fft_real_axis": ["fft_ref.py"], "fft_fastconv": ["fft_ref.py", "fastconv.py"]}
CHECKER_TEXT = {"fft_bfp": "the frame structure of the output (N consecutive beats from sof, valid held and data/exponent stable while the sink is not ready, the exponent constant over a frame)",
                "fft_mdc2": "the frame structure of the output (N/2 consecutive beats from sof, no unknowns)",
                "fft_real_axis": "the AXI4-Stream handshake rules on both streams, tlast positions, the source's no-pause obligation and the sink's no-stall promise",
                "fft_fastconv": "the AXI4-Stream handshake rules on both streams and the AXI4-Lite handshake and response rules on the register interface"}


def rewrite_imports(src: str) -> str:
    """`from arith.<pkg> import a [as b]` -> `import a [as b]`; `from arith.<pkg>.<mod> import x` -> `from <mod> import x` (the harness folder is flat)."""
    out = []
    for line in src.splitlines():
        m = re.match(r"^(\s*)from arith\.[\w.]+ import (\w+)( as \w+)?\s*$", line)
        if m and not re.match(r"^\s*from arith\.[\w.]+\.\w+ import", line):
            out.append(f"{m.group(1)}import {m.group(2)}{m.group(3) or ''}")
            continue
        m = re.match(r"^(\s*)from arith\.[\w.]+\.(\w+) import (.+)$", line)
        if m:
            out.append(f"{m.group(1)}from {m.group(2)} import {m.group(3)}")
            continue
        out.append(line)
    return "\n".join(out) + "\n"


def example(fn: str) -> tuple[str, str, int, list[str]]:
    s = ac.load_spec(fn)
    v = next(iter(s["variants"]))
    p = ac.merged_params(s, v, s["variants"][v]["exhaustive_points"][1])
    return v, __import__("json").dumps(p), ac.latency_of(s, v, p), list(s["variants"])


def readme(fn: str) -> str:
    s = ac.load_spec(fn)
    v, params, lat, variants = example(fn)
    c = s["contract"]
    modes = MODES[fn]
    L = [f"# Verification harness for {fn} ({s['title']})", "",
         "Generated by `python -m arith.tools.gen_harness_fft` (arith brief 161); the handwritten parts are `chk_top.sv` and `coverage.yaml`. This folder is a deliverable: rerun it against your own instance after you "
         "integrate or change the block. It needs nothing else from the repository.", "",
         "## What is in it", "", "| File | What |", "|---|---|",
         "| `model.py` and its support (" + ", ".join(f"`{x}`" for x in SUPPORT[fn]) + ") | the bit-exact model of the specification ([../spec.md](../spec.md)), in Python integers |",
         f"| `bench.py`, `frames.py`, `fcover.py`, `{fn}_cocotb.py` | the cocotb bench: drives frames or streams (directed stimuli: impulses, tones, corner values; random ones; the stalls and gaps the contract permits), compares every output with the model bit for bit and checks the latency |",
         "| `assertions.sv` | passive SystemVerilog checkers (simulation only): " + CHECKER_TEXT[fn] + ". Their error counters must stay 0 |",
         "| `chk_top.sv` | your instance with those checkers beside it, used by `run_harness.py --checker` |",
         "| `coverage.yaml` | the coverage targets (events the stimulus must produce, with minimum counts); `run_harness.py` fails a full run that misses one |",
         "| `run_harness.py` | the standalone runner (Icarus Verilog + cocotb) |", "",
         "## Running it against your instance", "",
         "Needs `iverilog`, Python 3, `pip install cocotb==2.0.1 pyyaml" + (" numpy" if fn == "fft_fastconv" else "") + "`.", "", "```",
         f"python3 run_harness.py --rtl my_{fn}.sv --top my_module --variant {v} --params '{params}' --latency {lat} --mode all --checker", "```", "",
         "- `--top` must have the ports listed in the specification under the same names, and every parameter of the specification (pass them all in `--params`; the model is built from them).",
         f"- `--latency` is your instance's latency in clocks as the specification defines it. Giving a wrong latency fails the run: that is deliberate, it checks the number. The latency of this block's variants (`{', '.join(variants)}`) is stated in `../spec.yaml` as a formula.",
         f"- `--mode` is one of `all` (default) or {', '.join(f'`{m}`' for m in modes)}: the modes are the benches of the repository's own tests (stimuli, schedules and checks described in `{fn}_cocotb.py`).",
         "- `--checker` builds your instance next to `assertions.sv`; the run fails if a checker counts a violation. To use the checkers in your own bench instead, instantiate them with the same signals as in `chk_top.sv`.",
         "- Exit status 0 means: every output matched the model, the latency and the checkers were as specified, and (mode `all`) every coverage target was met. `--build-dir` keeps the logs and the coverage files.", "",
         "## Interface the harness assumes", ""]
    L += [f"- Protocol: {c['protocol']}", f"- Throughput: {c['throughput']}", f"- Latency: {c['latency']}", f"- Reset: {c['reset']}", f"- Clock: {c['clock']}", f"- Stalls: {c['stall']}", "",
          "## What the harness does not cover", "",
          "- Timing, area and power: nothing here is a Vivado result. The harness checks function against the model, the interface rules and the stated latency, in simulation only.",
          "- A reset in the middle of a frame or a block, and parameter combinations outside the points of `../spec.yaml` (the model supports them; the harness is run at the points you give it).",
          "- The checkers are immediate assertions evaluated on the clock edge, not concurrent SVA properties (the open-source simulator does not run those).", ""]
    return "\n".join(L)


def outputs(fn: str) -> dict[Path, str]:
    h = ac.ARITH / fn / "harness"
    out: dict[Path, str] = {}
    out[h / "model.py"] = rewrite_imports((ac.ARITH / fn / "model.py").read_text())
    if fn == "fft_real_axis":
        out[h / "fft_real_model.py"] = rewrite_imports((ac.ARITH / "fft_real" / "model.py").read_text())
        out[h / "model.py"] = out[h / "model.py"].replace("import model as real_model", "import fft_real_model as real_model")
        out[h / "model.py"] = out[h / "model.py"].replace("from arith.fft_real import model as real_model", "import fft_real_model as real_model")
    for f in SUPPORT[fn]:
        out[h / f] = rewrite_imports((ac.ARITH / "fft_common" / f).read_text())
    out[h / "frames.py"] = rewrite_imports((ac.ARITH / "fft_common" / "frames.py").read_text())
    out[h / "fcover.py"] = (ac.ARITH / "fft_common" / "fcover.py").read_text()
    out[h / "bench.py"] = rewrite_imports((ac.ARITH / "tools" / "bench.py").read_text())
    out[h / f"{fn}_cocotb.py"] = rewrite_imports((ac.ARITH / fn / "tests" / f"{fn}_cocotb.py").read_text())
    hdr = f"// assertions.sv of {fn} (arith brief 161): the simulation checkers its chk_top.sv uses, copied from arith/fft_common by arith/tools/gen_harness_fft.py (do not edit).\n"
    out[h / "assertions.sv"] = hdr + "\n".join((ac.ARITH / "fft_common" / c).read_text() for c in CHECKERS[fn])
    v, params, lat, variants = example(fn)
    tpl = (ac.ARITH / "tools" / "run_harness_fft_template.py").read_text()
    out[h / "run_harness.py"] = (tpl.replace("@FN@", fn).replace("@VARIANT@", v).replace("@PARAMS@", params).replace("@LAT@", str(lat)).replace("@VARIANTS@", ", ".join(variants))
                                 .replace("@MODES_LIST@", repr(MODES[fn])).replace("@MODES@", ", ".join(MODES[fn])).replace("@NUMPY@", " and numpy" if fn == "fft_fastconv" else ""))
    out[h / "README.md"] = readme(fn)
    return out


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("functions", nargs="*", default=list(FUNCTIONS))
    ap.add_argument("--check", action="store_true")
    a = ap.parse_args()
    bad = 0
    for fn in a.functions:
        for p, t in outputs(fn).items():
            if a.check:
                if not p.exists() or p.read_text() != t:
                    print("out of date:", p.relative_to(ac.ROOT))
                    bad = 1
            else:
                p.parent.mkdir(parents=True, exist_ok=True)
                p.write_text(t)
    print("harness:", "FAIL" if bad else ("ok" if a.check else "written"))
    return bad


if __name__ == "__main__":
    sys.exit(main())
